// Simple Space Escape game
// Canvas with id="game" must exist in the HTML.

(() => {
  const canvas = document.getElementById('game');
  if (!canvas) return console.error('Canvas #game not found');
  const ctx = canvas.getContext('2d');
  const W = (canvas.width = canvas.offsetWidth || 800);
  const H = (canvas.height = canvas.offsetHeight || 600);

  // Ship definition
  const ship = {
    x: W / 2,
    y: H / 2,
    r: 12,
    angle: 0,
    speed: 0,
    fuel: 100,
    boostTime: 0,
  };

  const keys = {};
  document.addEventListener('keydown', e => (keys[e.key.toLowerCase()] = true));
  document.addEventListener('keyup', e => (keys[e.key.toLowerCase()] = false));

  const asteroids = [];
  const fuels = [];

  function spawnAsteroid() {
    const size = 15 + Math.random() * 20;
    asteroids.push({
      x: W + size,
      y: Math.random() * H,
      r: size,
      vx: - (1 + Math.random() * 2),
    });
  }

  function spawnFuel() {
    const r = 8;
    fuels.push({
      x: W + r,
      y: Math.random() * H,
      r,
      vx: -1.5,
    });
  }

  // Initial spawns
  for (let i = 0; i < 5; i++) spawnAsteroid();
  for (let i = 0; i < 2; i++) spawnFuel();

  function update(dt) {
    // Controls
    const turnSpeed = 0.003 * dt;
    if (keys['arrowleft'] || keys['a']) ship.angle -= turnSpeed;
    if (keys['arrowright'] || keys['d']) ship.angle += turnSpeed;
    if (keys['arrowup'] || keys['w']) ship.speed = 0.1 * dt;
    if (keys['arrowdown'] || keys['s']) ship.speed = -0.05 * dt;
    if (keys[' ']) {
      ship.boostTime = 200; // ms boost
    }
    if (ship.boostTime > 0) {
      ship.speed += 0.2 * dt;
      ship.boostTime -= dt;
    }
    // Apply movement
    ship.x += Math.cos(ship.angle) * ship.speed;
    ship.y += Math.sin(ship.angle) * ship.speed;
    // Keep inside bounds
    ship.x = (ship.x + W) % W;
    ship.y = (ship.y + H) % H;
    // Fuel consumption
    ship.fuel -= 0.02 * dt / 1000;
    // Update asteroids
    asteroids.forEach(a => (a.x += a.vx * dt * 0.001));
    // Update fuels
    fuels.forEach(f => (f.x += f.vx * dt * 0.001));
    // Remove off‑screen objects
    asteroids.filter(a => a.x + a.r > 0);
    fuels.filter(f => f.x + f.r > 0);
    // Spawn new obstacles/fuel periodically
    if (Math.random() < 0.01) spawnAsteroid();
    if (Math.random() < 0.005) spawnFuel();
    // Collision detection
    for (const a of asteroids) {
      const dx = a.x - ship.x, dy = a.y - ship.y;
      if (dx * dx + dy * dy < (a.r + ship.r) ** 2) {
        gameOver();
        return;
      }
    }
    for (let i = fuels.length - 1; i >= 0; i--) {
      const f = fuels[i];
      const dx = f.x - ship.x, dy = f.y - ship.y;
      if (dx * dx + dy * dy < (f.r + ship.r) ** 2) {
        ship.fuel = Math.min(ship.fuel + 30, 100);
        fuels.splice(i, 1);
      }
    }
    if (ship.fuel <= 0) {
      gameOver();
    }
  }

  function draw() {
    ctx.clearRect(0, 0, W, H);
    // Ship (triangle)
    ctx.save();
    ctx.translate(ship.x, ship.y);
    ctx.rotate(ship.angle);
    ctx.beginPath();
    ctx.moveTo(ship.r, 0);
    ctx.lineTo(-ship.r, ship.r / 2);
    ctx.lineTo(-ship.r, -ship.r / 2);
    ctx.closePath();
    ctx.fillStyle = '#0ff';
    ctx.fill();
    ctx.restore();
    // Asteroids (circles)
    ctx.fillStyle = '#888';
    asteroids.forEach(a => {
      ctx.beginPath();
      ctx.arc(a.x, a.y, a.r, 0, Math.PI * 2);
      ctx.fill();
    });
    // Fuel cells
    ctx.fillStyle = '#ff0';
    fuels.forEach(f => {
      ctx.beginPath();
      ctx.arc(f.x, f.y, f.r, 0, Math.PI * 2);
      ctx.fill();
    });
    // Fuel bar
    ctx.fillStyle = '#0f0';
    ctx.fillRect(10, 10, ship.fuel, 8);
    ctx.strokeStyle = '#000';
    ctx.strokeRect(10, 10, 100, 8);
  }

  let last = performance.now();
  let running = true;
  function loop(ts) {
    if (!running) return;
    const dt = ts - last;
    last = ts;
    update(dt);
    draw();
    requestAnimationFrame(loop);
  }

  function gameOver() {
    running = false;
    ctx.fillStyle = 'rgba(0,0,0,0.7)';
    ctx.fillRect(0, 0, W, H);
    ctx.fillStyle = '#fff';
    ctx.font = '48px sans-serif';
    ctx.textAlign = 'center';
    ctx.fillText('Game Over', W / 2, H / 2);
  }

  requestAnimationFrame(loop);
})();
